Q=[]
def q(id,topic,question,fmt,rule,source):
 dim={'C':'Kontext','O':'Ökologisch','W':'Ökonomisch','S':'Sozial','M':'Management'}[id[0]]
 Q.append(dict(id=id,dimension=dim,topic=topic,text=question,format=fmt,rule=rule,source=source,origin='Eigene Formulierung, aus den angegebenen Quellen abgeleitet'))
q('C1','Prozess','Welcher Prozess wird mit welchem Zweck, Startpunkt, Endpunkt und Qualitätsanspruch untersucht?','Kurzbeschreibung und Prozessgrenze','Pflichtangabe; keine Punkte.','L, Kap. 4; A, Kap. 2–3')
q('C2','Bezugsgröße','Welche funktionale Einheit beschreibt eine vergleichbare, erfolgreich erbrachte Leistung?','Einheit, Menge und Qualitätsanforderung, z. B. ein Transport über eine feste Strecke','Alternativen müssen denselben Nutzen erbringen.','L, Kap. 4; C, PDF 141')
q('C3','Ist und Soll','Welche Ausgangslösung und welche Alternative werden mit welchen Zielwerten verglichen?','Ist/Soll, Ziel, Zeitpunkt und Quelle des Zielwerts','Ziele vor der Auswertung festlegen; Planwerte getrennt halten.','T, PDF 53–60; C, PDF 164–170')
q('C4','Zeitraum und Systemgrenze','Welcher Zeitraum und welche vor- und nachgelagerten Schritte einschließlich Nutzung und Entsorgung sind einbezogen?','Zeitraum, Standort, Lebensweg, ausgeschlossene Schritte','Gleiche Grenzen verwenden; Ausschlüsse begründen.','K, PDF 31–38; A, Kap. 3–4')
q('C5','Betroffene','Welche Beschäftigten, Kunden, Lieferanten oder weiteren Gruppen sind vom Prozess betroffen?','Stakeholderliste und Art der Betroffenheit','Grundlage für soziale Fragen; keine Punkte.','C, PDF 144–146; A, PDF 253–262')
q('O1','Energie','Wie viel Energie benötigt der Prozess je funktionaler Einheit, getrennt nach Energieträgern und einschließlich relevanter Vorketten?','kWh/Einheit; Energieträger; Ist/Soll; Messzeitraum','Weniger bei gleicher Leistung ist besser. Erneuerbarenanteil und Energieeffizienz getrennt ausweisen.','L, Kap. 4.4; K, PDF 31–36')
q('O2','CO₂ und weitere Treibhausgase','Welche CO₂- und weiteren Treibhausgasemissionen entstehen je funktionaler Einheit über die festgelegten Lebenswegstufen?','kg CO₂e/Einheit; Emissionsfaktoren, Quellen, Jahr, Systemgrenze','Weniger ist besser; Herstellung und Betrieb nach derselben Methode erfassen. CO₂ ist Teil der CO₂e-Summe und wird nicht zusätzlich gewichtet.','K, PDF 31 und 41; L, PDF 85; A, Kap. 3')
q('O3','Material','Welche Materialmengen und kritischen Rohstoffe werden je funktionaler Einheit eingesetzt?','kg/Einheit; Materialarten; Anteil Sekundärmaterial in %','Materialarten getrennt bewerten. Weniger Masse allein belegt keine geringere Gesamtwirkung.','K, PDF 31–36; L, Kap. 4.3')
q('O4','Abfall und Kreislauf','Welche Abfälle entstehen und welche belegten Möglichkeiten zur Reparatur, Wiederverwendung oder Verwertung bestehen?','kg Abfall/Einheit; gefährlicher Anteil; tatsächliche Rücknahme-/Verwertungsquote; Lebensdauer','Technische Möglichkeit von tatsächlicher Nutzung trennen; geringere Abfallmenge positiv.','K, PDF 31–36; A, Kap. 4')
q('O5','Trinkwasser, Wasser und Abwasser','Wie viel Wasser und davon Trinkwasser wird je Einheit entnommen und verbraucht? Welche Menge und Qualität hat das zurückgeführte Abwasser, und wie knapp ist Wasser am Standort?','Liter/Einheit: Entnahme, Verbrauch und Rückleitung getrennt; Trinkwasseranteil; Herkunft, Einleitort und Zeitraum; Abwasserqualität: relevante Stoffkonzentrationen (mg/l) und Frachten (g/Einheit)','Verbrauch ist der im Bezugsgebiet und Zeitraum nicht zurückgeführte Anteil. Mengen, lokale Knappheit und Qualität gemeinsam prüfen. Weniger Abwasser oder Verdünnung allein belegt keine Verbesserung. Teilindikatoren vorab gewichten.','K, PDF 33 und 41; A, PDF 246 und 253–255')
q('O6','Lärm, Abwärme und weitere Belastungen','Welche Belastungen durch Lärm, Abwärme oder sonstige lokale Gefahrstoffeinträge verursacht der Prozess für sein Umfeld?','Einzelmesswerte, Messorte, Exposition und Maßnahmen','Belastungen einzeln prüfen. Abwasser unter O5, Luftschadstoffe unter O7 und Beschäftigtenexposition unter S1/S2 erfassen; dieselbe Wirkung im Index nicht doppelt zählen.','K, PDF 35; L, PDF 85; E, PDF 90–91')
q('O7','Luftqualität und Luftschadstoffe','Welche Luftschadstoffe entstehen durch den Prozess und relevante Vorketten je funktionaler Einheit, und welche Belastung der lokalen Luftqualität ist damit verbunden?','Stoffweise Emissionen in g/Einheit, z. B. NOₓ, SO₂, Feinstaub oder VOC; Emissionsort und Zeitraum; gegebenenfalls lokale Konzentrationen in µg/m³ mit Messort und Zuordnung','Gleiche Stoffe, Leistung und Systemgrenzen vergleichen. Verschiedene Schadstoffe nicht ungeprüft addieren. Emissionen und lokale Konzentrationen getrennt beurteilen; CO₂-Klimawirkung unter O2. Teilindikatoren vorab gewichten.','K, PDF 33–34 und 41; A, PDF 113')
q('O8','Flächennutzung und Flächenverbrauch','Welche Flächen beansprucht der Prozess einschließlich relevanter Vorketten, wie lange werden sie genutzt und wie viel Fläche wird neu versiegelt oder von naturnaher Nutzung umgewandelt?','Zugeordnete Fläche in m² und Nutzungsdauer; bei geeigneter Allokation m²·Jahr/Einheit; neu versiegelte oder umgewandelte m² im Zeitraum; Standort, Ausgangs- und Folgenutzung','Bestandsnutzung, Neuversiegelung und Umwandlung getrennt ausweisen. Gleiche Bezugsdauer und Allokation verwenden; Ausgangszustand und ökologische Empfindlichkeit berücksichtigen. Eine kleinere Anlage allein belegt keinen geringeren Gesamtflächenbedarf.','K, PDF 41; A, PDF 113 und 232')
q('W1','Gesamtkosten','Wie hoch sind Investitions-, Betriebs-, Wartungs-, Ausfall- und Entsorgungskosten über denselben Betrachtungszeitraum?','€ gesamt und €/Einheit; Preisbasis; Nutzungsdauer; Ist/Soll','Gleiche Leistung und Qualität vergleichen; Annahmen und gegebenenfalls Abzinsung offenlegen.','C, Kap. 1 und 7; E, PDF 89–91')
q('W2','Zeit und Produktivität','Wie lange dauert die definierte Leistung oder ein relevanter Teilprozess und welcher Durchsatz wird erreicht?','Minuten/Leistung oder Teilprozess; Einheiten/Stunde; Ist/Soll','Weniger Zeit bei gleicher Leistung positiv; Teilprozess nicht mit Gesamtprozess gleichsetzen.','L, PDF 119–127; E, PDF 89–91')
q('W3','Qualität und Nacharbeit','Wie hoch sind Fehler-, Ausschuss- und Nacharbeitsquote bei vergleichbarem Qualitätsanspruch?','% fehlerhafter Ergebnisse; Stunden oder €/Nacharbeit','Weniger ist besser. Fehlerkosten unter W1 konsistent behandeln; Doppelgewichtung vermeiden.','L, PDF 85 und 123; C, Kap. 1')
q('W4','Verfügbarkeit','Wie zuverlässig ist der Prozess und welche Ausfälle oder Wartungsunterbrechungen treten auf?','% Verfügbarkeit; Ausfallstunden; ungeplante Unterbrechungen','Höhere Verfügbarkeit bei gleichem Zeitraum positiv; Verbesserung braucht Vergleichsdaten.','L, Kap. 4.2 und PDF 123; E, PDF 91')
q('W5','Investition','Welche zusätzliche Investition ist nötig und unter welchen Annahmen ist sie wirtschaftlich tragfähig?','€ Investition; Einsparungen/Jahr; Amortisation oder Kapitalwert; Sensitivität','Kein allgemeiner Grenzwert. Nutzungsdauer, Unsicherheit und Mindestbedingungen dokumentieren.','C, Kap. 1 und 7; E, PDF 89')
q('W6','Robustheit','Wie verändert die Alternative die Abhängigkeit von Energiepreisen, Lieferanten, Ersatzteilen oder einzelnen Technologien?','Szenarien zu Preis, Verfügbarkeit und Ausfällen; Kostenbandbreiten','Szenarien vergleichbar rechnen; ein qualitatives Risiko ist noch keine monetäre Einsparung.','A, Kap. 2–3; T, Kap. 3–4; E, PDF 91')
q('S1','Gesundheit und Sicherheit','Welche arbeitsbedingten Gesundheits- und Sicherheitsrisiken bestehen und wie verändern sich Unfälle oder Expositionen?','Risiken und Schutzmaßnahmen; Ereignisse je Arbeitsstunden; Messwerte','Schwere ungelöste Risiken gesondert ausweisen; keine Verrechnung mit wirtschaftlichen Vorteilen.','L, PDF 85; E, Kap. 8 und PDF 90–91')
q('S2','Arbeitsbelastung','Wie verändert sich die körperliche und psychische Belastung der betroffenen Beschäftigten?','Ergonomische Messung oder identische Vor-/Nachher-Befragung; Stichprobe','Skala und Anker vorab festlegen; geringere Belastung positiv; subjektive Einschätzung kennzeichnen.','E, Kap. 8 und PDF 90–91; A, PDF 253–260')
q('S3','Qualifizierung','Welche Qualifizierung wird erreicht: Wie viele Personen werden geschult und welche Kompetenzen werden nachgewiesen?','Teilnehmerzahl/-anteil, Zielwert und Zeitraum; gesondert Lernerfolg oder Anwendung','Teilnahme ist ein Output. Kompetenz und längerfristige Wirkung getrennt prüfen.','A, PDF 260; L, PDF 124–125; C, PDF 147')
q('S4','Beteiligung','Wie werden Betroffene an der Prozessänderung beteiligt und wie werden ihre Rückmeldungen nachvollziehbar berücksichtigt?','Gruppen, Beteiligungsformat, Rückmeldungen und umgesetzte Änderungen','Mechanismus und erlebte Beteiligung getrennt erfassen; kein Wirkungsnachweis durch ein Gremium allein.','A, PDF 256–257; L, PDF 124–126; E, PDF 91')
q('S5','Zugang und Fairness','Wer kann die Prozessergebnisse nutzen und welche finanziellen, sprachlichen, körperlichen oder technischen Barrieren bestehen?','Zielgruppen; Zugang/Versorgung; Kostenbarrieren; Maßnahmen','Auch interne Nutzer berücksichtigen; Nichtanwendbarkeit begründen.','C, PDF 145–147; K, PDF 35–36; E, PDF 42')
q('S6','Tatsächlicher Nutzen','Welche Veränderung für Menschen ist über Aktivitäten und unmittelbare Ergebnisse hinaus nachgewiesen?','Vor-/Nachher-Wirkung, Vergleichsgruppe oder begründetes Wirkmodell; Unsicherheit','Aktivität, Output, Outcome und gesellschaftliche Wirkung unterscheiden; Kausalität nicht aus Stückzahlen ableiten.','C, PDF 141 und 146–149')
q('M1','Ziele','Sind konkrete, messbare Nachhaltigkeitsziele für den Prozess festgelegt und mit einem Zeitpunkt versehen?','Ziele, Sollwerte, Termin und Freigabe','Reifegrad 0–3 oder unbekannt; separat von Prozesswirkung.','K, PDF 36–38; T, PDF 53–60; C, PDF 166')
q('M2','Verantwortung','Sind Verantwortliche und benötigte Ressourcen für die Nachhaltigkeitsziele benannt?','Rolle, Zuständigkeit, Ressourcen und Entscheidungsrechte','Reifegrad 0–3 oder unbekannt; keine erreichte Wirkung daraus ableiten.','L, PDF 85 und 124–126; C, PDF 166–168')
q('M3','Datenerhebung','Werden Kennzahlen nach einer dokumentierten Methode regelmäßig erhoben und auf Plausibilität geprüft?','Quellen, Rhythmus, Messmethode und Qualitätssicherung','Reifegrad 0–3 oder unbekannt; Prozess-KPIs und Nachhaltigkeitskennzahlen unterscheiden.','K, PDF 38; L, PDF 85 und 123; C, PDF 146–148')
q('M4','Verbesserungszyklus','Werden Abweichungen besprochen, Maßnahmen umgesetzt und deren Ergebnisse erneut geprüft?','Reviewrhythmus, Maßnahmenliste, Verantwortliche und Nachprüfung','Reifegrad 0–3 oder unbekannt. Geplante Reviews sind kein laufender Zyklus.','L, PDF 126; T, PDF 59; C, PDF 166–170')
q('M5','Zielkonflikte','Werden Lebensweg, Zielkonflikte und mögliche Mehrverbräuche durch eine höhere Nutzung berücksichtigt?','Systemgrenzen, Zielkonflikte, Rebound-Szenarien und Entscheidungen','Reifegrad 0–3 oder unbekannt; wirtschaftliche Vorteile ersetzen keine Umwelt-/Sozialprüfung.','A, Kap. 2–4; K, PDF 31–38')
q('M6','Überprüfung','Wie wurden Daten, Wirkannahmen und Bewertungen durch Betroffene, Fachleute oder unabhängige Prüfungen überprüft?','Prüfgegenstand, Verfahren, Ergebnis, Unabhängigkeit und offene Punkte','Reifegrad 0–3 oder unbekannt. Modellprüfung von gemessener Wirkung unterscheiden.','L, PDF 82–87 und 126; C, PDF 169–171')

cases=[
dict(id='festo',name='Festo',subtitle='Digitale Prozessverbesserung',kind='Unternehmensbericht',color='#126d57',source='L, Kap. 6.7, PDF 119–127 (Buch S. 113–121)',summary='PUMA und ADEX machen Abläufe, Kennzahlen und Verbesserungen sichtbar. Schulung und Beteiligung sind beschrieben; vergleichbare Umwelt- und Ergebnisdaten fehlen.',takeaway='Vorlage für Datenerfassung, Beteiligung und einen Verbesserungszyklus.',next='Energie, Kosten, Qualität und Belastung für einen klar abgegrenzten Prozess vor und nach Einführung messen.'),
dict(id='mercedes',name='Mercedes-Benz',subtitle='Brennstoffzellen in der Intralogistik',kind='Pilot + Modell',color='#986b28',source='E, Kap. 6.4, PDF 89–91 (Buch S. 78–80)',summary='Der Pilot benennt technische Probleme. Die Betankung dauert acht Minuten statt der angestrebten drei bis fünf. Ökologische und wirtschaftliche Vorteile bleiben an Modellannahmen gebunden.',takeaway='Vorlage für einen Ist-Soll-Vergleich mit dokumentierten Zielkonflikten.',next='Batterie- und Brennstoffzellenbetrieb bei gleicher Transportleistung einschließlich Energie-Vorketten und Wartung vergleichen.'),
dict(id='hoeren',name='Hörgerätebranche',subtitle='Zugang, Qualifizierung und Wirkung',kind='Analyse von vier Herstellern',color='#5e608f',source='C, Kap. 9.4, PDF 144–149 (Buch S. 136–141)',summary='Die Analyse von Demant, GN Store Nord, Sonova und WS Audiology trennt Aktivitäten und Output von Wirkung. Sonova berichtet 270 geschulte Akustiker bei einem Ziel von 250.',takeaway='Vorlage für die soziale Dimension und die Unterscheidung von Output und Wirkung.',next='Hersteller getrennt untersuchen und Zugangs-, Nutzungs- und Wirkungsdaten einheitlich erheben.'),
dict(id='scrum',name='SustainableScrum',subtitle='Nachhaltigkeit in Softwareprojekten',kind='Vorgehenskonzept',color='#316c88',source='C, Kap. 10, PDF 164–171 (Buch S. 157–164)',summary='Controller, Nachhaltigkeits-Backlog und Review ergänzen Scrum im vorgeschlagenen Modell. Die Prüfung ist konzeptionell; gemessene Ergebnisse eines Praxistests fehlen.',takeaway='Vorlage, um Nachhaltigkeitsziele in der Softwareentwicklung verbindlich zu verankern.',next='Konzept in einem Projekt erproben: Aufwand, Nutzen, Energie, Team-Belastung und Zielerreichung messen.')]
answers={c['id']:{} for c in cases}
def a(case,id,status,text,missing='',ref=None,grade=None,number=None):
 c=next(c for c in cases if c['id']==case)
 answers[case][id]=dict(status=status,text=text,missing=missing,ref=ref or c['source'],grade=grade,number=number)
contexts={
'festo':['Elektronikproduktion und administrative Prozesse in Sofia; PUMA für Maschinendaten, ADEX für indirekte Prozesse. Der Fall umfasst mehrere Prozesse.','Nicht festgelegt. Eigener Vorschlag: ein spezifikationsgerechtes Elektronikmodul; administrative Leistungen separat behandeln.','PUMA/ADEX werden als eingeführt beschrieben. Ein abgegrenzter quantitativer Ausgangszustand und konsistente Zielwerte fehlen.','Standortbezogener Bericht mit Entwicklungsschritten seit 2013; kein einheitlicher Messzeitraum und keine vollständige Lebenswegabgrenzung.','Maschinenbediener, Teams, Team- und Abteilungsleitungen sowie lokale und zentrale OPEX-Unterstützung.'],
'mercedes':['Interne Logistik in Düsseldorf; Vergleich von Blei-Batterie- und Brennstoffzellenfahrzeugen. Betankung und Wartung sind Teilprozesse.','Für den Gesamtvergleich nicht festgelegt. Eigener Vorschlag: gleiche Last über gleiche Strecke. Die Zeitangabe im Buch bezieht sich auf eine Betankung.','Brennstoffzellenfahrzeuge werden seit 2020 im Dreischichtbetrieb getestet. Betankung: 8 min; Ziel: 3–5 min. Vollständige Batterie-Referenzwerte fehlen.','Pilot und ökonomisches Modell; Energiebereitstellung wird diskutiert, aber keine vollständige quantifizierte Lebenswegbilanz berichtet.','Fahrer, Projektleitungen, Fahrzeug-/Brennstoffzellenhersteller, Infrastrukturpartner und SRH Hochschule.'],
'hoeren':['Analyse sozialer Berichterstattung von vier Herstellern, kein einzelner Betriebsprozess.','Verschiedene Größen: versorgte Personen, Tests, geschulte Personen und modellierte Nutzungsjahre. Keine gemeinsame funktionale Einheit.','Mehrere herstellerspezifische Ziele; Sonova: 270 ausgebildete Akustiker gegenüber Ziel 250. Zukunftsziele anderer Hersteller sind nicht als erreicht zu interpretieren.','Berichte 2023/2024, Fokus auf nachgelagerte soziale Themen. Sonova-Schulung: zwei berichtete Geschäftsjahre; keine Gesamtbilanz.','Menschen mit Hörminderung, Menschen mit geringem Einkommen, Kinder, Fachpersonal, Kliniken und Partner.'],
'scrum':['Konzeptionelle Scrum-Erweiterung mit Controller, Nachhaltigkeits-Backlog und Review.','Nicht operationalisiert. Eigener Vorschlag: gleichwertige Nutzeranforderungen bei festem Qualitätsniveau. Story Points eignen sich nicht für organisationsübergreifende Vergleiche.','Messbare Ziele je Sprint sind vorgesehen; konkreter Ist-Zustand, umgesetzter Pilot und Ergebniswerte fehlen.','Konzeptentwicklung und logische Evaluation; kein empirischer Messzeitraum. Projektarbeit und Wirkung des Produkts getrennt betrachten.','Team, Scrum Master, Product Owner, Sustainability Controller, Business Owner und Kunden/Stakeholder.']}
for c in cases:
 for i,t in enumerate(contexts[c['id']],1):a(c['id'],f'C{i}','context',t)
 for qx in Q:
  if qx['id'] not in answers[c['id']]:a(c['id'],qx['id'],'gap','Im ausgewerteten Fallabschnitt keine ausreichende Angabe zu dieser Frage.',qx['format']+'.')

a('festo','W1','qual','Der Bericht nennt verbesserte Kosteneffizienz, ohne Gesamtkosten oder Differenz auszuweisen.','Kosten inklusive Software, Schulung, Wartung und Betrieb vor/nach Einführung.','L, PDF 127, Abschluss Kap. 6.7')
a('festo','W2','qual','PUMA analysiert Engpässe; 5S soll Suchzeiten reduzieren.','Tatsächliche Durchlaufzeit und Durchsatz bei gleicher Qualität.','L, PDF 120 und 126')
a('festo','W3','qual','QCD-Kennzahlen, Störungsmeldungen und digitale Problemlösung sind beschrieben.','Fehler- und Nacharbeitsquoten vor/nach Einführung.','L, PDF 123')
a('festo','W4','qual','Maschinenzustände werden überwacht; Störungsbearbeitung und Wartung werden unterstützt.','Verfügbarkeit und Ausfallstunden mit Referenz.','L, PDF 120 und 123')
a('festo','S3','qual','Regelmäßige Schulungen, Handbücher und ADEX-Trainings werden beschrieben.','Teilnehmerquote und nachgewiesener Kompetenzgewinn.','L, PDF 124–125')
a('festo','S4','qual','Officefloor-Boards erlauben Rückmeldungen von Teams und Führungskräften; Ideen fließen auch von unten ein.','Erlebte Beteiligung und dokumentierte Umsetzung von Vorschlägen.','L, PDF 125–126')
a('festo','M1','qual','Prozessvision und Fortschritt sind auf Boards sichtbar; quantifizierte ökologische und soziale Prozessziele fehlen.','Nachhaltigkeitsziele mit Sollwert und Termin.','L, PDF 126',1)
a('festo','M2','qual','Abteilungsleitungen führen Verbesserungsbereiche; lokale und zentrale OPEX-Teams unterstützen.','Zuständigkeit für alle drei Nachhaltigkeitsdimensionen.','L, PDF 124–125',2)
a('festo','M3','qual','PUMA erstellt tägliche, wöchentliche und monatliche KPI-Berichte. Das belegt Prozessmonitoring.','Ökologische/soziale Messreihen und dokumentierte Datenprüfung.','L, PDF 123',2)
a('festo','M4','qual','PDCA mit Selbstbewertung, Umsetzung, externem ADEX-Assessment und Lessons Learned wird beschrieben.','Nachhaltigkeitswirkungen anhand vergleichbarer Messwerte.','L, PDF 126',3)
a('festo','M6','qual','Externe ADEX-Assessments und Empfehlungen betreffen Prozess-/Organisationsentwicklung.','Unabhängige Prüfung von Umwelt- und Sozialwirkungen.','L, PDF 126',2)

a('mercedes','O1','qual','Der Text benennt die höhere Effizienz der Blei-Batterie gegenüber der Brennstoffzellenkette. Verbräuche fehlen.','kWh für gleiche Transportleistung inklusive Umwandlung.','E, PDF 89')
a('mercedes','O2','plan','Ökologische Vorteile werden unter Annahmen über grünen Wasserstoff und dessen Bereitstellung diskutiert; eine verifizierte CO₂-Bilanz fehlt.','kg CO₂e/Transport für beide Alternativen und Energieherkunft.','E, PDF 89–90')
a('mercedes','O6','qual','Anfangs erhöhte Wärme- und Geräuschentwicklung wurde durch Änderungen an Hard- und Software reduziert.','Messwerte, Exposition und Wirkung auf das Umfeld.','E, PDF 90')
a('mercedes','O8','plan','Die Flächenargumentation zum Modell nennt weniger als 1 m² für die Wasserstoffpumpe und bei optimaler Auslastung bis zu 60 Fahrzeuge pro Schicht. Die freizuhaltende Betankungsfläche kommt hinzu. Das ist eine Komponentenangabe im Modellkontext, keine gemessene Gesamtflächenbilanz oder belegte Einsparung.','Gesamtflächen beider Alternativen einschließlich Betankungs-/Sicherheitsflächen, Speicherung und relevanter Vorketten; Nutzungsdauer und Zuordnung zur Transportleistung; Neuversiegelung und vorherige Flächennutzung.','E, PDF 89')
